	for (ull i = 1; i < a.size(); ++i) {
		res = crt(res.first, res.second, mod(a[i], m[i]), m[i]);
		if (res.second == -1) break;
	}
	return res;
}


ll SIZE;
vector<bool> bs;
vector<ll> primes;

void sieve(ll size = 1e6+10) { // call at start in main!
	SIZE = size; bs.assign(SIZE+1,1);
	bs[0] = bs[1] = 0;
	for (ll i = 2; i <= SIZE; i++) if (bs[i]) {
		for (ll j = i * i; j <= SIZE; j += i) bs[j] = 0;
		primes.push_back(i);
	}
}

bool is_prime(ll n) { // for N <= SIZE^2
	if (n <= SIZE) return bs[n];
	for(const auto &prime : primes)
	   	if (n % prime == 0) return false;
	return true;
}

struct Factor{ll prime; ll exp;}; using Fs = vector<Factor>;
Fs factor(ll n) {
	Fs factors;
	for(const auto &prime : primes){
		if(n==1 || prime*prime > n) break;
		ll exp=0;
		while(n % prime == 0)
		   	n/=prime, exp++;
		if(exp>0)
			factors.push_back({prime,exp});
	}
	if (n != 1) factors.push_back({n,1});
	return factors;
}

constexpr ll M = 1e9+7;

struct S{
	ll div, children, divsum, x;
};
vector<S> divisors(const Fs &fs){
	vector<S> ds{{1,1,1,0}}; // pair<divisor, divisors>
	ds.reserve(accumulate(fs.begin(),fs.end(),1, [](ll a,auto f){return a*(f.exp+1);}));
	for(auto f : fs)
		for(auto d : ds){
			ll sumpow = 1;
			ll pow = 1;
			for(ll i = 0; i < f.exp; ++i){
				pow *= f.prime;
				sumpow += pow;
				ds.push_back({d.div*pow, d.children*(i+2), d.divsum * sumpow,0});
			}
		}
	return ds;
}


vi fac;

ll binom(ll a, ll b){
	ll ans;
	if(b <0 || b>a) ans=0;
	else ans = fac[a] * mod_inverse(fac[b] * fac[a-b] % M, M) %M;
	Log("binom",a,b,ans);
	return ans;
}

